// ---------- Small building blocks ----------

function StatusPill({ status }) {
  const map = {
    requested: { bg: "#F1E7D1", fg: "#8A6A21", label: "Requested" },
    assigned: { bg: "#DCEAE6", fg: C.teal, label: "Assigned" },
    in_progress: { bg: "#FCEBD5", fg: "#B0701A", label: "In progress" },
    completed: { bg: "#E3EFE0", fg: "#3E7A3A", label: "Completed" },
  };
  const s = map[status];
  return (
    <span
      style={{
        background: s.bg, color: s.fg, fontFamily: "'IBM Plex Mono', monospace",
        fontSize: 11, padding: "3px 8px", borderRadius: 20, letterSpacing: 0.3,
      }}
    >
      {s.label}
    </span>
  );
}

// The signature element: an airmail-stripe journey track marking request progress
function JourneyTrack({ log }) {
  const activeIdx = log.filter((l) => l.done).length - 1;
  return (
    <div style={{ padding: "18px 4px 6px" }}>
      <div style={{ position: "relative", height: 2 }}>
        <div
          style={{
            position: "absolute", top: 0, left: 0, right: 0, height: 3,
            backgroundImage: `repeating-linear-gradient(90deg, ${C.line} 0 10px, transparent 10px 14px)`,
          }}
        />
        <div
          style={{
            position: "absolute", top: 0, left: 0, height: 3,
            width: `${(activeIdx / (STEPS.length - 1)) * 100}%`,
            backgroundImage: `repeating-linear-gradient(90deg, ${C.marigold} 0 8px, ${C.teal} 8px 16px)`,
            transition: "width 0.4s ease",
          }}
        />
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", marginTop: -11 }}>
        {STEPS.map((s, i) => {
          const done = i <= activeIdx;
          return (
            <div key={s} style={{ display: "flex", flexDirection: "column", alignItems: "center", width: 60 }}>
              <div
                style={{
                  width: 20, height: 20, borderRadius: "50%",
                  background: done ? C.teal : "#fff", border: `2px solid ${done ? C.teal : C.line}`,
                  display: "flex", alignItems: "center", justifyContent: "center",
                }}
              >
                {i === activeIdx ? (
                  <Plane size={11} color="#fff" style={{ transform: "rotate(45deg)" }} />
                ) : done ? (
                  <CheckCircle2 size={13} color="#fff" />
                ) : (
                  <Circle size={6} color={C.line} fill={C.line} />
                )}
              </div>
              <div
                style={{
                  fontFamily: "'Work Sans', sans-serif", fontSize: 9.5, marginTop: 6,
                  textAlign: "center", color: done ? C.charcoal : C.charcoalSoft, lineHeight: 1.2,
                }}
              >
                {STEP_LABEL[s]}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function TopBar({ title, onBack, right }) {
  return (
    <div
      style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "14px 16px 12px", background: C.teal, color: "#fff",
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 8, minHeight: 24 }}>
        {onBack && (
          <button onClick={onBack} style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", padding: 0 }}>
            <ChevronLeft size={22} />
          </button>
        )}
        <span style={{ fontFamily: "'Spectral', serif", fontSize: 18, fontWeight: 600 }}>{title}</span>
      </div>
      {right}
    </div>
  );
}

function Card({ children, onClick, style }) {
  return (
    <div
      onClick={onClick}
      style={{
        background: C.sandCard, borderRadius: 14, padding: 14, marginBottom: 12,
        border: `1px solid ${C.line}`, cursor: onClick ? "pointer" : "default", ...style,
      }}
    >
      {children}
    </div>
  );
}

function Button({ children, onClick, variant = "primary", full, disabled }) {
  const styles = {
    primary: { background: disabled ? "#C9B98E" : C.marigold, color: "#3A2A00" },
    secondary: { background: C.tealLight, color: C.teal },
    dark: { background: C.teal, color: "#fff" },
    ghost: { background: "transparent", color: C.teal, border: `1px solid ${C.teal}` },
  };
  return (
    <button
      onClick={disabled ? undefined : onClick}
      style={{
        ...styles[variant], border: styles[variant].border || "none", borderRadius: 10,
        padding: "12px 16px", fontFamily: "'Work Sans', sans-serif", fontWeight: 600,
        fontSize: 14, width: full ? "100%" : "auto", cursor: disabled ? "default" : "pointer",
        display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
      }}
    >
      {children}
    </button>
  );
}

